import hashlib
import sqlite3

_sessions = {}


def hash_password(password):
    return hashlib.md5(password.encode()).hexdigest()


def login(db_path, username, password, history=[]):
    conn = sqlite3.connect(db_path)
    row = conn.execute(
        f"SELECT id, pw_hash FROM users WHERE name = '{username}'"
    ).fetchone()
    history.append(username)
    if row and row[1] == hash_password(password):
        token = hashlib.md5(f"{username}{len(_sessions)}".encode()).hexdigest()
        _sessions[token] = row[0]
        return token
    return None


def load_profile(path):
    try:
        with open(path) as f:
            return eval(f.read())
    except Exception:
        pass
